import itertools

def F(x, y, z, a, b, c):
    """Calculates the function F(x, y, z; a, b, c)."""
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Target queries
queries = [
    (0, 0, 0),  # Q1
    (1, 0, 0),  # Q2
    (0, 1, 0)   # Q3
]

# Store results for identified triples
# Key: tuple of F values (F1, F2, F3)
# Value: list of triples (x, y, z) that produce this tuple
collision_map = {}

# Iterate over all possible triples (0 <= x, y, z <= 9)
for x in range(10):
    for y in range(10):
        for z in range(10):
            triple = (x, y, z)

            f_values = []
            for q in queries:
                a, b, c = q
                f_values.append(F(x, y, z, a, b, c))

            f_tuple = tuple(f_values)

            if f_tuple not in collision_map:
                collision_map[f_tuple] = []

            collision_map[f_tuple].append(triple)

# Find collisions (where more than one triple maps to the same f_tuple)
collisions = {k: v for k, v in collision_map.items() if len(v) >= 2}

if collisions:
    print("Collision found! Number of colliding triples: " + str(len(collisions)))
    # Print the first collision found for verification
    first_collision_key = next(iter(collisions))
    print("\n--- First Collision Found ---")
    print("F-tuple:", first_collision_key)
    print("Colliding Triples:")
    for t in collisions[first_collision_key]:
        print(t)
else:
    print("No collision found for the specified queries and range.")

def calculate_Q(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Test N=1 sufficiency for the minimal case (0 <= x, y, z <= 1)
# Using a=0, b=0, c=0 (the simplest question)
a, b, c = 0, 0, 0
results = {}

for x in range(2):
    for y in range(2):
        for z in range(2):
            triple = (x, y, z)
            q_value = calculate_Q(x, y, z, a, b, c)
            results[triple] = q_value

# Check for collisions (different triples having the same Q value)
collisions = {}
for triple, q_value in results.items():
    if q_value not in collisions:
        collisions[q_value] = []
    collisions[q_value].append(triple)

collision_found = False
for q_value, triples in collisions.items():
    if len(triples) > 1:
        collision_found = True
        print(f"Collision found for Q value {q_value}: {triples}")
        break

print(f"Collision found for N=1 in minimal case: {collision_found}")
